    57→public class DataColumnSidecarsByRangeMessageHandler
    58→    extends PeerRequiredLocalMessageHandler<
    59→        DataColumnSidecarsByRangeRequestMessage, DataColumnSidecar> {
    60→
    61→  private static final Logger LOG = LogManager.getLogger();
    62→
    63→  private final SpecConfigFulu specConfigFulu;
