    67→  private final DasReqRespLogger dasLogger;
    68→
    69→  public DataColumnSidecarsByRangeMessageHandler(
    70→      final SpecConfigFulu specConfigFulu,
    71→      final MetricsSystem metricsSystem,
    72→      final CombinedChainDataClient combinedChainDataClient,
    73→      final DasReqRespLogger dasLogger) {
    74→    this.specConfigFulu = specConfigFulu;
    75→    this.combinedChainDataClient = combinedChainDataClient;
    76→    requestCounter =
    77→        metricsSystem.createLabelledCounter(
    78→            TekuMetricCategory.NETWORK,
    79→            "rpc_data_column_sidecars_by_range_requests_total",
    80→            "Total number of data column sidecars by range requests received",
    81→            "status");
