    83→        metricsSystem.createCounter(
    84→            TekuMetricCategory.NETWORK,
    85→            "rpc_data_column_sidecars_by_range_requested_sidecars_total",
    86→            "Total number of data column sidecars requested in accepted blob sidecars by range requests from peers");
    87→    this.dasLogger = dasLogger;
    88→  }
    89→
    90→  @Override
    91→  public Optional<RpcException> validateRequest(
    92→      final String protocolId, final DataColumnSidecarsByRangeRequestMessage request) {
    93→    final int maxRequestDataColumnSidecars = specConfigFulu.getMaxRequestDataColumnSidecars();
    94→    final int requestedCount = calculateRequestedCount(request);
    95→
    96→    if (requestedCount == -1 || requestedCount > maxRequestDataColumnSidecars) {
    97→      requestCounter.labels("count_too_big").inc();
    98→      return Optional.of(
    99→          new RpcException(
   100→              INVALID_REQUEST_CODE,
   101→              String.format(
   102→                  "Only a maximum of %s data column sidecars can be requested per request",
   103→                  maxRequestDataColumnSidecars)));
   104→    }
   105→    return Optional.empty();
   106→  }
   107→
   108→  @Override
   109→  public void onIncomingMessage(
   110→      final String protocolId,
   111→      final Eth2Peer peer,
   112→      final DataColumnSidecarsByRangeRequestMessage message,
   113→      final ResponseCallback<DataColumnSidecar> responseCallback) {
   114→    final UInt64 startSlot = message.getStartSlot();
   115→    final UInt64 endSlot = message.getMaxSlot();
   116→    final List<UInt64> columns = message.getColumns();
   117→
   118→    final ReqRespResponseLogger<DataColumnSidecar> responseLogger =
   119→        dasLogger
   120→            .getDataColumnSidecarsByRangeLogger()
   121→            .onInboundRequest(
   122→                LoggingPeerId.fromPeerAndNodeId(
   123→                    peer.getId().toBase58(), peer.getDiscoveryNodeId().orElseThrow()),
   124→                new DasReqRespLogger.ByRangeRequest(
   125→                    message.getStartSlot(), message.getCount().intValue(), message.getColumns()));
   126→    final LoggingResponseCallback<DataColumnSidecar> responseCallbackWithLogging =
   127→        new LoggingResponseCallback<>(responseCallback, responseLogger);
   128→
   129→    final int requestedCount = calculateRequestedCount(message);
   130→
   131→    final Optional<RequestKey> maybeRequestKey =
   132→        peer.approveDataColumnSidecarsRequest(responseCallbackWithLogging, requestedCount);
   133→
   134→    if (!peer.approveRequest() || maybeRequestKey.isEmpty()) {
   135→      requestCounter.labels("rate_limited").inc();
   136→      return;
   137→    }
   138→
   139→    requestCounter.labels("ok").inc();
   140→    totalDataColumnSidecarsRequestedCounter.inc(message.getCount().longValue());
   141→
   142→    UInt64 finalizedSlot = combinedChainDataClient.getFinalizedBlockSlot().orElse(UInt64.ZERO);
   143→
   144→    final SortedMap<UInt64, Bytes32> canonicalHotRoots;
